%[text] ## Harmonic Array
%[text] Construct the Toeplitz Block Form and BlockToeplitz form of order h using the BT and TB method
h=5 %[output:664d4bae]

%TB and BT matrix
A.T_tb(h) %[output:370ed9cf]
A.T_bt(h) %[output:1b4532a1]

%en version sparse
A.spBT(h) %[output:588ca412]
A.spTB(h) %[output:52bc97a0]

T=1 %period %[output:46814c65]
nx=2 %number of state %[output:3fc6442a]
N_tb(nx,h,T) %[output:2f0c8cbc]
N_bt(nx,h,T) %[output:8cf7526a]

spN_bt(nx,h,T) %[output:1123f164]
spN_tb(nx,h,T) %[output:66407be7]
figure %[output:3798cb83]
barsurf(A.T_tb(10),'EdgeColor','interp') %[output:3798cb83]
view([0 90.00]) %[output:3798cb83]

%[text] The 'N' function accept a phasorArray as first argument and deduce from the first dimension of the matrix the number of state
N_tb(A,h,T) %[output:980b8014]
%[text] to compute the square hankel form used in LMI use
%[text]  \[$\\mathcal{H}\_{m,m}(A^+)\\mathcal{J}\_{m,m},\\mathcal{J}\_{m,m}\\mathcal{H}\_{m,m}(A^-),\\mathcal{H}\_{m,m}(A^+),\\mathcal{H}\_{m,m}(A^-)\]=A.TBHankel(h);$
%[text] BT hankel is not yet implemented
[HpJ,JHm,Hp,Hm]=A.TBHankel(h);
% [HpJ,JHm,Hp,Hm]=A.BTHankel(h); 

%sparse versions
[HpJ,JHm,Hp,Hm]=A.spTBHankel(h);
%[text] compute eigenvalue of A and eigen value of A-N
A.HmqNEig(h,T) %[output:4d3ee61d]
A.HmqEig(h) %[output:2b72a0f2]

%[text] Output sincos form, imag real form etc in the form of 3D array
u=ScalarPhasorArray([1 1/2 -1/2/1i],"isreal",1) %[output:75bb5100]
% u = 1 + cos - sin
figure %[output:9695c61a]
plot(u,1,0:0.01:2,title='u') %[output:9695c61a]

u.SinCosForm %[output:57927f7f]
u.ImagRealForm %[output:5fc536f7]
%%
%[text] ## Symbolic and sdpvar
%[text] The toolbox allows for definition of symbolic and sdp variable in the form of PhasorArray to perform all the previous operations
hP=5 %[output:3c623155]

%liste de sdp var servant aux phaseur 
P2=(sdpvar(size(A,1),size(A,2),hP,'symmetric','complex')) %[output:7ef1a3c1]
%sdpvar phaseur 0 (réel)
P1=(ndsdpvar(size(A,1),size(A,2),1,'symmetric','real')) %[output:1d1f51b4]
%sdpvar phaseur array
P = PosPart2PhasorArray(P1,P2) %[output:6fb4a619]
PT=P.T_tb(h) %[output:4eb56510]

%ou directement avec la methode statique de PhasorArray
P = PhasorArray.ndsdpvar(2,2,5,PhasorType='symmetric',real=true) %[output:05347b3c]

P=sdpval(P) %[output:7b90b08e]
% P = value(value(P))
%to extract the value in P after optim
%[text] see LMI example for more details
%[text] 
%[text] Also, symbolic phasorArray are available
S = PhasorArray.sym(2,2,5,'s') %[output:62cb99ed]
S.T_tb(3) %[output:21ec6b83]
S.TBHankel(3) %[output:5df72824]

R = PhasorArray.random(2,2,2) %[output:71f2c718]

SymPlusR=T_tb(S+R,3) %[output:123cbf6b]
vpa(SymPlusR,3) %[output:6bc83472]
SymTimesR=T_tb(S*R,3) %[output:71e52764]
vpa(SymTimesR,3) %[output:7613882e]
%%
%[text] ## Lyapunov and Sylvester eq
A=mreal(rand_phasor(4,4,7,"hurwitzeig",[-1 -0.7 -0.1 -0.3],"time_structure","hurwitz",output="PhasorArray")) %[output:888c4f33]
Q=PhasorArray(eye(4));

hp=10;
T0=1;

%A^TP + PA +Q =0
P=PhasorArray(SylvHarmonic(A',A,Q,2*hp,2*pi/T0));
figure %[output:25b4da32]
clf %[output:25b4da32]
plot(P) %[output:25b4da32]
P2 = A.lyap(Q,"T",T0,"thresholdResidual",1e-8) %auto adapt h until accuracy is reached %[output:840c373f] %[output:11138bbb]
hold on %[output:25b4da32]
plot(P2) %[output:25b4da32]

figure %[output:5ffb7aff]
clf %[output:5ffb7aff]
plot(real(P.HmqEig(40)),'*') %[output:5ffb7aff]

nx=size(A,1) %[output:07b1e2e8]
nz=2 %[output:5c6a2bdb]

C=PhasorArray(rand_phasor(nz,nx,4,"time_structure","real")) %[output:9481e6ff]
O=rand(nz,nz) %[output:3055a150]

%-OM + MA -C =0
M=PhasorArray(SylvHarmonic(-O,A,-C,2*hp,2*pi/T0));
plot(M) %[output:5ffb7aff]

